/* AnnouncementMapper.updateAnnouncement */
UPDATE center_ann_board_post
SET
ttl = #{ttl}
, cn = #{cn}
, top_fix_yn = NVL(#{topFixYn}, 'N')
, pblanc_bgng_dt = TO_DATE(#{pblancBgngDt}, 'YYYY-MM-DD')
, pblanc_end_dt = TO_DATE(#{pblancEndDt}, 'YYYY-MM-DD')
, rcrt_bgng_dt = TO_DATE(#{rcrtBgngDt}, 'YYYY-MM-DD')
, rcrt_end_dt = TO_DATE(#{rcrtEndDt}, 'YYYY-MM-DD')
, atch_file_id = #{atchFileId}
, opn_yn = NVL(#{opnYn}, 'Y')
, mdf_dttm = SYSDATE
WHERE ann_no = #{annNo}

/* AnnouncementMapper.deleteAnnouncement */
UPDATE center_ann_board_post
SET
del_yn = 'Y'
, mdf_dttm = SYSDATE
WHERE ann_no = #{annNo}
